bool retain_nsb_director_dependency(
    DirectorHandle& owner,
    DirectorHandle& dependency,
    int object_slot) noexcept {
    try {
        const std::shared_ptr<DirectorControl> owner_control = owner.SharedControl();
        const std::shared_ptr<DirectorControl> dependency_control = dependency.SharedControl();
        if (object_slot < 0 || owner_control == nullptr || !owner_control->IsAlive() ||
            dependency_control == nullptr || !dependency_control->IsAlive() ||
            owner_control->StateObjectAddress(object_slot) !=
                reinterpret_cast<std::uintptr_t>(dependency_control->BaseAddress())) {
            return false;
        }
        owner_control->RetainDependency(dependency_control);
        return true;
    } catch (...) {
        return false;
    }
}

